function makeBotSquad(seed){const target={GK:2,DEF:5,MID:5,FWD:3};const ids=[];Object.entries(target).forEach(([pos,count])=>players.filter(p=>p.pos===pos).sort((a,b)=>((a.id*(seed+7)+seed*31)%997)-((b.id*(seed+7)+seed*31)%997)).slice(0,count).forEach(p=>ids.push(p.id)));return ids}
