let deadlineTarget=null;let chipState={used:{wildcard:false,freeHit:false,benchBoost:false,tripleCaptain:false},active:null};const kitClass={Liverpool:"kit-liverpool",Arsenal:"kit-arsenal","Crystal Palace":"kit-crystal-palace",Tottenham:"kit-tottenham",Chelsea:"kit-chelsea","Man City":"kit-man-city","Man United":"kit-man-united",Newcastle:"kit-newcastle","Aston Villa":"kit-aston-villa",Brighton:"kit-brighton",Barcelona:"kit-barcelona","Real Madrid":"kit-real-madrid",PSG:"kit-psg"};const faceCache=new Map(Object.entries(window.playerPhotos||{}));const profile=p=>{const initials=p.n.split(" ").map(x=>x[0]).join("").slice(0,2);const cached=faceCache.get(p.n)||fallbackPlayerPhoto;return `<div class="player-avatar player-profile ${kitClass[p.club]||"kit-default"}" data-profile-id="${p.id}" role="img" aria-label="${p.n} in ${p.club} kit"><img class="player-face" src="${cached}" alt="${p.n}" loading="lazy" decoding="async" onerror="this.remove()"><span>${initials}</span></div>`};const hydrateProfiles=list=>{list.forEach(async p=>{if(faceCache.has(p.n)&&faceCache.get(p.n)){const cachedFace=faceCache.get(p.n);const card=document.querySelector(`[data-profile-id="${p.id}"]`);if(card&&cachedFace)card.classList.add("has-face");if(cachedFace)document.querySelectorAll(`[data-face-id="${p.id}"]`).forEach(face=>{face.src=cachedFace});return}try{const r=await fetch("https://en.wikipedia.org/api/rest_v1/page/summary/"+encodeURIComponent(p.n));const d=await r.json();const src=d.thumbnail?.source||"";faceCache.set(p.n,src);const card=document.querySelector(`[data-profile-id="${p.id}"]`);const img=card?.querySelector(".player-face");if(src&&img){img.src=src;img.addEventListener("load",()=>card.classList.add("has-face"),{once:true});document.querySelectorAll(`[data-face-id="${p.id}"]`).forEach(face=>{face.src=src})}}catch{faceCache.set(p.n,"");}})};
function load(){try{const x=JSON.parse(localStorage.getItem("fantasyuefa-squad")||"{}");selected=(x.selected||[]).filter(id=>players.some(p=>p.id===id));captain=x.captain||"";vice=x.vice||"";if(x.formation)$("formation").value=x.formation;transferHistory=JSON.parse(localStorage.getItem("fantasyuefa-transfers")||"[]");const savedChips=JSON.parse(localStorage.getItem("fantasyuefa-chips")||"null");if(savedChips)chipState={...chipState,...savedChips,used:{...chipState.used,...(savedChips.used||{})}};const savedLeague=JSON.parse(localStorage.getItem("fantasyuefa-bot-league")||"null");if(savedLeague&&Array.isArray(savedLeague.scores)&&savedLeague.scores.length===botManagers.length+1){botLeague=savedLeague;if(!Array.isArray(botLeague.squads))botLeague={round:0,scores:Array.from({length:botManagers.length+1},()=>0),lastPoints:{},squads:[]}}matchdayPoints=botLeague.lastPoints||{};ensureBotSquads()}catch{selected=[];captain="";vice="";transferHistory=[]}}
function cost(){return selected.reduce((s,id)=>s+(players.find(p=>p.id===id)?.price||0),0)}
function limits(){return {GK:2,DEF:5,MID:5,FWD:3}}
function validAdd(p){if(selected.includes(p.id))return "Already selected";if(selected.length>=15)return "Squad is full";if(selected.filter(id=>players.find(x=>x.id===id)?.pos===p.pos).length>=limits()[p.pos])return "Position limit reached";if(cost()+p.price>100)return "Not enough budget";if(selected.filter(id=>players.find(x=>x.id===id)?.club===p.club).length>=3)return "Maximum 3 players per club";return ""}
function recordTransfer(type,p){transferHistory.unshift({type,name:p.n,club:p.club,price:p.price,at:new Date().toISOString()});transferHistory=transferHistory.slice(0,20);try{localStorage.setItem("fantasyuefa-transfers",JSON.stringify(transferHistory))}catch{}}
function add(id){const p=players.find(x=>x.id===id);if(!p){toast("Player not found");return}const err=validAdd(p);if(err){toast(err);return}selected.push(id);recordTransfer("IN",p);render();toast(p.n+" transferred in")}
function remove(id){const p=players.find(x=>x.id===id);if(!p||!selected.includes(id))return;selected=selected.filter(x=>x!==id);if(captain==id)captain="";if(vice==id)vice="";recordTransfer("OUT",p);render();toast(p.n+" transferred out")}
function showProfile(id){const p=players.find(x=>x.id===Number(id));if(!p)return;const modal=$("playerModal");if(!modal)return;const img=faceCache.get(p.n)||"";$("modalPlayerName").textContent=p.n;$("modalPlayerClub").textContent=p.club+" · "+p.pos;$("modalPlayerPrice").textContent="£"+p.price.toFixed(1)+"m";$("modalPlayerAvatar").innerHTML=profile(p);$("modalPlayerAvatar").className="modal-avatar "+(kitClass[p.club]||"kit-default");const image=$("modalPlayerAvatar").querySelector("img");if(img&&image){image.src=img;image.style.display="block";image.onerror=()=>image.remove()}$("modalPlayerBio").textContent="Premier League fantasy player · "+p.pos+" · "+p.club+". Player stats and real-time points are not connected in this demo.";$("modalTransferBtn").textContent=selected.includes(p.id)?"Transfer out of squad":"Transfer into squad";$("modalTransferBtn").onclick=()=>{if(selected.includes(p.id))remove(p.id);else add(p.id);modal.classList.remove("open");modal.setAttribute("aria-hidden","true")};modal.classList.add("open");modal.setAttribute("aria-hidden","false")}
