function botStartingXI(ids){const pool=ids.map(id=>players.find(p=>p.id===id)).filter(Boolean);const target={GK:1,DEF:4,MID:4,FWD:2};return Object.entries(target).flatMap(([pos,count])=>pool.filter(p=>p.pos===pos).slice(0,count))}
let liveMatchday={active:false,round:0,minute:0,timer:null,userXI:null,botXI:[]};
function playerFixture(p,round){return fixtures.find(x=>x.comp==="Premier League"&&(x.home===p.club||x.away===p.club))}
function playerPlayed(p,round){const f=playerFixture(p,round);if(!f)return false;return (p.id*31+round*47+p.club.length*13)%100%9!==0}
function autoSubstitute(starters,bench,round){const active=starters.slice(),used=[],subs=[];active.forEach((p,i)=>{if(playerPlayed(p,round))return;const replacement=bench.find(b=>b.pos===p.pos&&playerPlayed(b,round)&&!used.includes(b.id));if(replacement){active[i]=replacement;used.push(replacement.id);subs.push({out:p,in:replacement})}});return {starters:active,subs}}
function userLineupForRound(round){const starters=currentStarters(),starterIds=new Set(starters.map(p=>p.id)),bench=selected.map(id=>players.find(p=>p.id===id)).filter(Boolean).filter(p=>!starterIds.has(p.id));return autoSubstitute(starters,bench,round)}
function fixtureScore(f,round){const seed=(f.home.length*17+f.away.length*29+round*41)%100;return {home:seed%4,away:Math.floor(seed/4)%4}}
function liveFixtureScore(f,round,minute){const final=fixtureScore(f,round),hash=(f.home.length*19+f.away.length*23+round*37)%80;const goals=(side,total,offset)=>Array.from({length:total},(_,i)=>((hash+offset+i*29)%80)+5).filter(t=>t<=minute).length;return {home:goals("home",final.home,0),away:goals("away",final.away,17)}}
function fixtureScoreLabel(f){if(liveMatchday.active&&liveMatchday.round){const score=liveFixtureScore(f,liveMatchday.round,liveMatchday.minute);return score.home+" - "+score.away+" · "+liveMatchday.minute+"'"}if(!botLeague.round)return "VS";const score=fixtureScore(f,botLeague.round);return score.home+" - "+score.away}
function fixturePoints(p,round){const f=playerFixture(p,round);if(!f||!playerPlayed(p,round))return 0;const score=fixtureScore(f,round),home=p.club===f.home,goalsAgainst=home?score.away:score.home;const seed=(p.id*31+round*47+p.club.length*13)%100;let pts=2;const goals=p.pos==="FWD"?(seed%11===0?1:0):p.pos==="MID"?(seed%17===0?1:0):p.pos==="DEF"?(seed%29===0?1:0):0;const assists=seed%13===0?1:0;pts+=goals*(p.pos==="FWD"?4:p.pos==="MID"?5:6)+assists*3;if(goalsAgainst===0&&(p.pos==="GK"||p.pos==="DEF"))pts+=4;else if(goalsAgainst===0&&p.pos==="MID")pts+=1;if(seed%23===0)pts=Math.max(0,pts-1);if(seed%97===0)pts=Math.max(0,pts-3);return pts}
function livePlayerPoints(p,round,minute){if(!playerPlayed(p,round)||minute<=0)return 0;return minute>=90?fixturePoints(p,round):Math.floor(fixturePoints(p,round)*minute/90)}
function lineupScore(xi,round,minute,captainId,viceId,benchBoost){const pool=xi.filter(Boolean).filter(p=>benchBoost||playerPlayed(p,round));const playedIds=new Set(pool.map(p=>p.id));const multiplierId=playedIds.has(Number(captainId))?Number(captainId):playedIds.has(Number(viceId))?Number(viceId):null;return pool.reduce((sum,p)=>sum+livePlayerPoints(p,round,minute)*(p.id===multiplierId?2:1),0)}
function botMatchdayPoints(index,round){const xi=botStartingXI(botLeague.squads[index]||[]),captain=xi.slice().sort((a,b)=>fixturePoints(b,round)-fixturePoints(a,round))[0],vice=xi.find(p=>p.id!==captain?.id);return lineupScore(xi,round,90,captain?.id,vice?.id,false)}
function botLivePoints(index){const xi=(liveMatchday.botXI[index]||{}).starters||[],captain=xi.slice().sort((a,b)=>fixturePoints(b,liveMatchday.round)-fixturePoints(a,liveMatchday.round))[0],vice=xi.find(p=>p.id!==captain?.id);return lineupScore(xi,liveMatchday.round,liveMatchday.minute,captain?.id,vice?.id,false)}
function userLivePoints(){if(!liveMatchday.userXI)return 0;return lineupScore(chipState.active==="benchBoost"?selected.map(id=>players.find(p=>p.id===id)).filter(Boolean):liveMatchday.userXI.starters,liveMatchday.round,liveMatchday.minute,captain,vice,chipState.active==="benchBoost")}
function renderBotLeague(){const el=$("botLeagueTable");if(!el)return;ensureBotSquads();const competitors=[{name:"Your Team",short:"YOU"},...botManagers];const rows=competitors.map((bot,i)=>({bot,i,score:(botLeague.scores[i]||0)+(liveMatchday.active?(i===0?userLivePoints():botLivePoints(i-1)):0)})).sort((a,b)=>b.score-a.score);el.innerHTML=rows.map((row,pos)=>'<div class="bot-row '+(row.i===0?'bot-user':'')+'"><span class="bot-rank">'+(pos+1)+'</span><span class="bot-badge">'+row.bot.short+'</span><span class="bot-name">'+row.bot.name+'</span><strong>'+row.score+'</strong><small>pts</small></div>').join("");const cards=$("botSquadCards");if(cards)cards.innerHTML=botManagers.map((bot,i)=>{const squad=(botLeague.squads[i]||[]).map(id=>players.find(p=>p.id===id)).filter(Boolean);const xi=botStartingXI(botLeague.squads[i]||[]);return '<article class="bot-squad-card"><div class="bot-squad-heading"><span class="bot-badge">'+bot.short+'</span><div><b>'+bot.name+'</b><small>'+xi.length+' starters · '+squad.length+' players</small></div></div><div class="bot-squad-list">'+squad.map(p=>'<span>'+p.n+' <em>'+p.club+'</em></span>').join("")+'</div></article>'}).join("");const msg=$("botLeagueMessage");if(msg)msg.textContent=liveMatchday.active?"Live matchday · "+liveMatchday.minute+"' · scores and fixture points are updating.":botLeague.round?"Matchday "+botLeague.round+" complete · Fixture points saved on this device.":"Each rival has a 15-player squad. Start the live fixture matchday to score points."}
function finalizeLiveMatchday(){const round=liveMatchday.round;const userXI=liveMatchday.userXI||userLineupForRound(round);matchdayPoints=Object.fromEntries(players.map(p=>[p.id,fixturePoints(p,round)]));botLeague.round=round;botLeague.lastPoints=matchdayPoints;botLeague.lastAutoSubs={user:userXI.subs.map(x=>({out:x.out.id,in:x.in.id})),bots:liveMatchday.botXI.map(x=>x.subs.map(y=>({out:y.out.id,in:y.in.id})))};botLeague.scores[0]+=lineupScore(chipState.active==="benchBoost"?selected.map(id=>players.find(p=>p.id===id)).filter(Boolean):userXI.starters,round,90,captain,vice,chipState.active==="benchBoost");botManagers.forEach((_,i)=>{botLeague.scores[i+1]+=botMatchdayPoints(i,round)});if(chipState.active){chipState.used[chipState.active]=true;chipState.active=null;saveChips()}if(liveMatchday.timer)clearInterval(liveMatchday.timer);liveMatchday={active:false,round:0,minute:0,timer:null,userXI:null,botXI:[]};saveBotLeague();const button=$("simulateMatchday");if(button){button.disabled=false;button.innerHTML="Start live matchday <span>↗</span>"}render();renderFixtures();renderBotLeague();toast("Matchday "+round+" complete — bench substitutions applied")}
function updateLiveMatchday(){if(!liveMatchday.active)return;liveMatchday.minute=Math.min(90,liveMatchday.minute+15);renderFixtures();renderBotLeague();if(liveMatchday.minute>=90)finalizeLiveMatchday()}
function startLiveMatchday(){if(liveMatchday.active){toast("This matchday is already live");return}ensureBotSquads();const round=botLeague.round+1;liveMatchday={active:true,round,minute:0,timer:null,userXI:userLineupForRound(round),botXI:botLeague.squads.map(ids=>autoSubstitute(botStartingXI(ids),ids.map(id=>players.find(p=>p.id===id)).filter(Boolean).filter(p=>!botStartingXI(ids).some(x=>x.id===p.id)),round))};const button=$("simulateMatchday");if(button){button.disabled=true;button.innerHTML="Live matchday · 0' <span>●</span>"}renderFixtures();renderBotLeague();liveMatchday.timer=setInterval(updateLiveMatchday,1500);toast("Live matchday started — automatic substitutions enabled")}
function renderTransfers(){const el=$("transferHistory");if(!el)return;el.innerHTML=transferHistory.length?transferHistory.map(t=>'<div class="transfer-item"><span class="transfer-tag '+(t.type==="IN"?"transfer-in":"transfer-out")+'">'+t.type+'</span><span><b>'+t.name+'</b><small>'+t.club+'</small></span><strong>£'+t.price.toFixed(1)+'m</strong></div>').join(""):'<p class="fine-print">Your transfer activity will appear here.</p>'}
function toast(s){const t=$("toast");t.textContent=s;t.classList.add("show");clearTimeout(window.fuToast);window.fuToast=setTimeout(()=>t.classList.remove("show"),2200)}
function renderPlayers(){const q=$("playerSearch").value.toLowerCase();const pos=$("positionFilter").value;const list=players.filter(p=>(pos==="All"||p.pos===pos)&&(p.n+" "+p.club).toLowerCase().includes(q));$("playerList").innerHTML=list.map(p=>{const on=selected.includes(p.id);return '<div class="player-row">'+profile(p)+'<div><div class="player-name">'+p.n+'</div><div class="player-meta">'+p.club+' · '+p.pos+'</div></div><div class="player-price">£'+p.price.toFixed(1)+'m</div><button class="add-btn" aria-label="'+(on?"Remove":"Add")+' '+p.n+'" data-player="'+p.id+'" '+(!on&&!!validAdd(p)?'disabled':'')+'>'+ (on?'−':'+')+'</button></div>'}).join("")||'<p class="fine-print">No Premier League players match your search.</p>';$("playerList").querySelectorAll("[data-player]").forEach(b=>b.addEventListener("click",()=>selected.includes(+b.dataset.player)?remove(+b.dataset.player):add(+b.dataset.player)));$("playerList").querySelectorAll("[data-profile-id]").forEach(a=>a.addEventListener("click",()=>showProfile(a.dataset.profileId)));hydrateProfiles(list.slice(0,60))}
function renderPitch(){const form=$("formation").value.split("-").map(Number);const chosen=selected.map(id=>players.find(p=>p.id===id)).filter(Boolean);const by=pos=>chosen.filter(p=>p.pos===pos);const gk=by("GK"),def=by("DEF"),mid=by("MID"),fwd=by("FWD");const rows=[{players:gk.slice(0,1),slots:1},{players:def.slice(0,form[0]),slots:form[0]},{players:mid.slice(0,form[1]),slots:form[1]},{players:fwd.slice(0,form[2]),slots:form[2]}];$("formationPlayers").innerHTML=rows.map(row=>'<div class="pitch-row">'+Array.from({length:row.slots},(_,j)=>{const p=row.players[j],src=faceCache.get(p?.n)||"";return '<button type="button" class="pitch-player '+(!p?'empty':'')+'" '+(p?'data-pitch-profile="'+p.id+'"':'disabled')+' aria-label="'+(p?'View '+p.n:'Empty lineup slot')+'"><div class="lineup-photo">'+(p?'<img class="pitch-face" data-face-id="'+p.id+'" src="'+src+'" alt="'+p.n+' face" loading="lazy" onload="this.classList.add(\'loaded\');" onerror="this.style.display=\'none\';"><span class="lineup-pos">'+p.pos+'</span>':'＋')+'</div><span>'+(p?p.n.split(" ").slice(-1)[0]:"Open slot")+'</span></button>'}).join("")+'</div>').join("");$("formationPlayers").querySelectorAll("[data-pitch-profile]").forEach(b=>b.addEventListener("click",()=>showProfile(b.dataset.pitchProfile)));const opts='<option value="">Choose player</option>'+chosen.map(p=>'<option value="'+p.id+'">'+p.n+'</option>').join("");$("captain").innerHTML=opts;$("vice").innerHTML=opts;$("captain").value=captain;$("vice").value=vice;const starters=chosen.filter(p=>p.pos==="GK").slice(0,1).concat(chosen.filter(p=>p.pos==="DEF").slice(0,form[0]),chosen.filter(p=>p.pos==="MID").slice(0,form[1]),chosen.filter(p=>p.pos==="FWD").slice(0,form[2]));const bench=chosen.filter(p=>!starters.includes(p));$("bench").innerHTML=Array.from({length:4},(_,i)=>{const p=bench[i],src=faceCache.get(p?.n)||"";return '<div class="bench-player">'+(p?'<img class="bench-face" src="'+src+'" data-face-id="'+p.id+'" alt="'+p.n+' face" loading="lazy" onerror="this.style.display=\'none\';">':'')+'<b>'+(p?p.n.split(" ").slice(-1)[0]:"Empty")+'</b><span>'+(p?p.pos:"SUB "+(i+1))+'</span></div>'}).join("");hydrateProfiles(chosen)}

function saveChips(){try{localStorage.setItem("fantasyuefa-chips",JSON.stringify(chipState))}catch{} }
function renderChips(){document.querySelectorAll("[data-chip]").forEach(btn=>{const name=btn.dataset.chip;const used=!!chipState.used[name];btn.classList.toggle("active",chipState.active===name);btn.classList.toggle("used",used);btn.disabled=used;btn.setAttribute("aria-pressed",chipState.active===name?"true":"false");const small=btn.querySelector("small");if(small)small.textContent=used?"Used this season":chipState.active===name?"Active for next matchday":({wildcard:"Free squad changes",freeHit:"Temporary squad",benchBoost:"Bench points count",tripleCaptain:"Captain scores ×3"}[name])});const status=$("chipsStatus");if(status)status.textContent=chipState.active?({wildcard:"Wildcard active",freeHit:"Free Hit active",benchBoost:"Bench Boost active",tripleCaptain:"Triple Captain active"}[chipState.active]):Object.values(chipState.used).every(Boolean)?"All chips used":"No chip active"}
function activateChip(name){if(chipState.used[name]){toast("That chip has already been used");return}if(chipState.active===name){chipState.active=null;saveChips();renderChips();toast("Chip cancelled");return}chipState.active=name;saveChips();renderChips();toast(({wildcard:"Wildcard",freeHit:"Free Hit",benchBoost:"Bench Boost",tripleCaptain:"Triple Captain"}[name])+" ready for the next matchday")}
function fplPoints(p,round){const seed=(p.id*29+round*47)%100;let pts=seed%6===0?1:2;const goals=p.pos==="FWD"?(seed%4===0?1:0):p.pos==="MID"?(seed%7===0?1:0):p.pos==="DEF"?(seed%17===0?1:0):0;const assists=seed%6===0?1:0;const clean=(p.pos==="GK"||p.pos==="DEF")&&seed%3!==0;const saves=p.pos==="GK"?(seed%4)+1:0;pts+=goals*(p.pos==="FWD"?4:p.pos==="MID"?5:p.pos==="DEF"?6:0)+assists*3+(clean?(p.pos==="GK"?4:p.pos==="DEF"?4:1):0)+Math.floor(saves/3)+(seed>70?1+(seed%3):0);return pts}
function currentStarters(){const form=$("formation").value.split("-").map(Number);const chosen=selected.map(id=>players.find(p=>p.id===id)).filter(Boolean);return chosen.filter(p=>p.pos==="GK").slice(0,1).concat(chosen.filter(p=>p.pos==="DEF").slice(0,form[0]),chosen.filter(p=>p.pos==="MID").slice(0,form[1]),chosen.filter(p=>p.pos==="FWD").slice(0,form[2]))}
function userFplPoints(){if(!Object.keys(matchdayPoints).length)return 0;const pool=chipState.active==="benchBoost"?selected.map(id=>players.find(p=>p.id===id)).filter(Boolean):currentStarters();const captainMultiplier=chipState.active==="tripleCaptain"?3:2;return pool.reduce((sum,p)=>sum+(matchdayPoints[p.id]||0)*(String(captain)===String(p.id)?captainMultiplier:1),0)}
function renderTeamOfWeek(){const el=$("teamOfWeek");if(!el)return;const ids=Object.keys(matchdayPoints);if(!ids.length){el.innerHTML='<p class="fine-print">Simulate a matchday to reveal the best XI.</p>';return}const pick=(pos,n)=>players.filter(p=>p.pos===pos).sort((a,b)=>(matchdayPoints[b.id]||0)-(matchdayPoints[a.id]||0)).slice(0,n);const xi=[...pick("GK",1),...pick("DEF",3),...pick("MID",4),...pick("FWD",3)];el.innerHTML=xi.map(p=>'<div class="week-player"><img class="week-face" data-face-id="'+p.id+'" src="'+(faceCache.get(p.n)||"")+'" alt="'+p.n+' face" loading="lazy" onerror="this.style.display=\'none\';"><span><b>'+p.n+'</b><small>'+p.club+' · '+p.pos+'</small></span><strong>'+(matchdayPoints[p.id]||0)+'<em>pts</em></strong></div>').join("");hydrateProfiles(xi)}
function updateDeadline(){const now=new Date();if(!deadlineTarget||deadlineTarget<=now){deadlineTarget=new Date(now);const days=(8-now.getDay())%7;deadlineTarget.setDate(now.getDate()+days);deadlineTarget.setHours(8,30,0,0);if(deadlineTarget<=now)deadlineTarget.setDate(deadlineTarget.getDate()+7)}const ms=deadlineTarget-now;const total=Math.max(0,Math.floor(ms/1000));const d=Math.floor(total/86400),h=Math.floor(total%86400/3600),m=Math.floor(total%3600/60),sec=total%60;const el=$("transferDeadline");if(el)el.textContent="Deadline "+(d?d+"d ":"")+String(h).padStart(2,"0")+":"+String(m).padStart(2,"0")+":"+String(sec).padStart(2,"0")}
function autoPick(){selected=[];captain="";vice="";const target={GK:2,DEF:5,MID:5,FWD:3};Object.entries(target).forEach(([pos,n])=>players.filter(p=>p.pos===pos).sort((a,b)=>(fplPoints(b,botLeague.round+1)/b.price)-(fplPoints(a,botLeague.round+1)/a.price)).some(p=>{if(selected.filter(id=>players.find(x=>x.id===id)?.pos===pos).length>=n)return true;const err=validAdd(p);if(!err){selected.push(p.id);return selected.filter(id=>players.find(x=>x.id===id)?.pos===pos).length>=n}return false}));players.slice().sort((a,b)=>(fplPoints(b,botLeague.round+1)/b.price)-(fplPoints(a,botLeague.round+1)/a.price)).forEach(p=>{if(selected.length<15&&!validAdd(p))selected.push(p.id)});if(selected.length===15){captain=String(selected.find(id=>players.find(p=>p.id===id)?.n==="Erling Haaland")||selected[0]);vice=String(selected.find(id=>id!==Number(captain))||selected[1]);render();toast("Auto-pick squad selected")}else toast("Auto-pick could not complete a valid squad")}
const statKey=name=>name.toLowerCase().replace(/[øðþß]/g,c=>({ø:"o",ð:"d",þ:"th",ß:"ss"}[c])).normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]/g,"");
function renderPlayerStats(){const el=$("playerStatsList");if(!el)return;const rows=players.map(p=>{const st={appearances:0,goals:0,assists:0,cleanSheets:0,yellowCards:0,redCards:0};return {p,st,score:(st.goals||0)+(st.assists||0)+(st.cleanSheets||0)}}).sort((a,b)=>b.score-a.score||a.p.n.localeCompare(b.p.n));const val=x=>x===null||x===undefined?"—":x;el.innerHTML='<div class="club-table-scroll"><div class="player-stats-row player-stats-head"><span>#</span><span>Player</span><span>Club</span><span>Starts</span><span>Goals</span><span>Assists</span><span>Clean Sheets</span><span>YC</span><span>RC</span></div>'+rows.map((r,i)=>'<div class="player-stats-row"><span>'+String(i+1).padStart(3,"0")+'</span><span class="club-table-name"><img src="'+(faceCache.get(r.p.n)||fallbackPlayerPhoto)+'" alt="'+r.p.n+' photo" loading="lazy" onerror="this.src=\''+fallbackPlayerPhoto+'\';"><b>'+r.p.n+'</b></span><span class="player-stat-club"><img src="'+clubLogoUrl(r.p.club)+'" alt="'+r.p.club+' crest" onerror="this.style.display=\'none\';">'+r.p.club+'</span><span>'+val(r.st.appearances)+'</span><span>'+val(r.st.goals)+'</span><span>'+val(r.st.assists)+'</span><span>'+val(r.st.cleanSheets)+'</span><span>'+val(r.st.yellowCards)+'</span><span>'+val(r.st.redCards)+'</span></div>').join("")+'</div>'}
function renderClubTable(){const el=$("clubTableList");if(!el)return;const clubs=Object.keys(clubLogos),rows=clubs.map(club=>{let mp=0,w=0,d=0,l=0,gf=0,ga=0;for(let r=1;r<=botLeague.round;r++)fixtures.forEach(f=>{if(f.home!==club&&f.away!==club)return;const x=fixtureScore(f,r),home=f.home===club,forGoals=home?x.home:x.away,against=home?x.away:x.home;mp++;gf+=forGoals;ga+=against;if(forGoals>against)w++;else if(forGoals===against)d++;else l++});if(liveMatchday.active)fixtures.forEach(f=>{if(f.home!==club&&f.away!==club)return;const x=liveFixtureScore(f,liveMatchday.round,liveMatchday.minute),home=f.home===club,forGoals=home?x.home:x.away,against=home?x.away:x.home;mp++;gf+=forGoals;ga+=against;if(forGoals>against)w++;else if(forGoals===against)d++;else l++});return {club,mp,w,d,l,gf,ga,gd:gf-ga,pts:w*3+d}}).sort((a,b)=>b.pts-a.pts||b.gd-a.gd||b.gf-a.gf);el.innerHTML='<div class="club-table-scroll"><div class="club-standings-row club-standings-head"><span>#</span><span>Club</span><span>MP</span><span>W</span><span>D</span><span>L</span><span>GF</span><span>GA</span><span>GD</span><span>Pts</span></div>'+rows.map((r,i)=>'<div class="club-standings-row"><strong>'+(i+1)+'</strong><span class="player-stat-club"><img src="'+clubLogoUrl(r.club)+'" alt="'+r.club+' crest" onerror="this.style.display=\'none\';">'+r.club+'</span><span>'+r.mp+'</span><span>'+r.w+'</span><span>'+r.d+'</span><span>'+r.l+'</span><span>'+r.gf+'</span><span>'+r.ga+'</span><span>'+r.gd+'</span><b>'+r.pts+'</b></div>').join("")+'</div>'}
function fixturePlayerStats(f,round,minute){const list=players.filter(p=>p.club===f.home||p.club===f.away).filter(p=>minute?playerPlayed(p,round):true).map(p=>({p,pts:minute?livePlayerPoints(p,round,minute):fixturePoints(p,round)})).sort((a,b)=>b.pts-a.pts);return list.slice(0,6).map(x=>'<span><b>'+x.p.n+'</b><em>'+x.p.club+' · '+x.pts+' pts</em></span>').join("")}
function render(){renderPlayers();renderPitch();renderTransfers();renderBotLeague();renderTeamOfWeek();renderChips();renderClubTable();renderPlayerStats();$("playersSelected").innerHTML=selected.length+'<span class="small-total"> / 15</span>';$("squadValue").textContent="£"+cost().toFixed(1)+"m";$("budgetChip").textContent="£"+(100-cost()).toFixed(1)+"m left";$("pointsTotal").textContent=String(userFplPoints());$("squadMessage").textContent=selected.length===15?"Squad complete! Set your captain and save.":selected.length+" of 15 players selected · Demo data";$("saveMessage").textContent="Your squad saves in this browser on this device."}
function renderFixtures(){const list=fixtures;$('fixtureList').innerHTML=list.slice(0,10).map(f=>{const logo=competitionLogos[f.comp]||"";const cls=f.comp==="Champions League"?" cl-logo":"";const homeLogo=clubLogoUrl(f.home),awayLogo=clubLogoUrl(f.away);const team=(name,url,side)=>'<div class="fixture-team fixture-team-'+side+'" title="'+name+'"><img class="club-badge" src="'+url+'" alt="'+name+' club crest" loading="lazy" decoding="async" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'inline\';"><span class="fixture-team-fallback">'+name+'</span></div>';return '<div class="fixture">'+team(f.home,homeLogo,"home")+'<div class="fixture-mid"><img class="fixture-logo'+cls+'" src="'+logo+'" alt="'+(f.comp==="Champions League"?"UEFA Champions League":f.comp)+' logo" loading="lazy" decoding="async" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'block\';"><span class="fixture-logo-fallback" aria-hidden="true">PL</span><b>'+fixtureScoreLabel(f)+'</b>'+f.date+'<div class="fixture-player-stats">'+((liveMatchday.active&&liveMatchday.minute>0)||botLeague.round?fixturePlayerStats(f,liveMatchday.active?liveMatchday.round:botLeague.round,liveMatchday.active?liveMatchday.minute:90):'<span class="fixture-not-played">Not played yet</span>')+'</div><br><span>'+f.tag+'</span></div>'+team(f.away,awayLogo,"away")+'</div>'}).join("")}
function save(){if(selected.length!==15){toast("Pick all 15 players first");return}const cnt={GK:2,DEF:5,MID:5,FWD:3};if(Object.entries(cnt).some(([pos,n])=>selected.filter(id=>players.find(p=>p.id===id)?.pos===pos).length!==n)){toast("Check your position balance");return}if(!captain||!vice||captain===vice){toast("Choose different captain and vice-captain");return}localStorage.setItem("fantasyuefa-squad",JSON.stringify({selected,captain,vice,formation:$("formation").value}));$("saveMessage").textContent="Saved on this device at "+new Date().toLocaleTimeString();toast("Squad saved on this device!")}
document.querySelectorAll("[data-comp]").forEach(b=>b.addEventListener("click",()=>{currentComp="Premier League";document.querySelectorAll("[data-comp]").forEach(x=>x.classList.toggle("active",x===b));renderPlayers();renderFixtures()}));$("playerSearch").addEventListener("input",renderPlayers);$("positionFilter").addEventListener("change",renderPlayers);$("formation").addEventListener("change",renderPitch);$("captain").addEventListener("change",e=>captain=e.target.value);$("vice").addEventListener("change",e=>vice=e.target.value);$("saveSquad").addEventListener("click",save);$("clearSquad").addEventListener("click",()=>{if(confirm("Clear your selected squad?")){selected=[];captain="";vice="";localStorage.removeItem("fantasyuefa-squad");render();toast("Squad cleared")}});$("autoPick").addEventListener("click",autoPick);document.querySelectorAll("[data-chip]").forEach(btn=>btn.addEventListener("click",()=>activateChip(btn.dataset.chip)));$("simulateMatchday").addEventListener("click",startLiveMatchday);$("resetBotLeague").addEventListener("click",()=>{if(confirm("Reset the bot league?")){if(liveMatchday.timer)clearInterval(liveMatchday.timer);liveMatchday={active:false,round:0,minute:0,timer:null,userXI:null,botXI:[]};botLeague={round:0,scores:Array.from({length:botManagers.length+1},()=>0),lastPoints:{},squads:botManagers.map((_,i)=>makeBotSquad(i+1))};matchdayPoints={};saveBotLeague();renderBotLeague();renderTeamOfWeek();toast("Bot league reset")}});$("profileBtn").addEventListener("click",()=>toast("Accounts will be added with the backend."));$("closePlayerModal").addEventListener("click",()=>{$("playerModal").classList.remove("open");$("playerModal").setAttribute("aria-hidden","true")});$("playerModal").addEventListener("click",e=>{if(e.target===$("playerModal")){$("playerModal").classList.remove("open");$("playerModal").setAttribute("aria-hidden","true")}});document.addEventListener("keydown",e=>{if(e.key==="Escape"){$("playerModal").classList.remove("open");$("playerModal").setAttribute("aria-hidden","true")}});load();render();renderFixtures();renderBotLeague();renderTeamOfWeek();updateDeadline();setInterval(updateDeadline,1000);function activateView(view){const mainSections=[...document.querySelector("main").children];mainSections.forEach(el=>el.classList.add("view-hidden"));const nav=[...document.querySelectorAll("[data-view]")];nav.forEach(a=>a.classList.toggle("active-view",a.dataset.view===view));const hero=document.querySelector(".hero"),competition=$("dashboard"),stats=document.querySelector(".stats-row"),content=document.querySelector(".content-grid"),bottom=document.querySelector(".bottom-grid");const squad=$("squad"),team=document.querySelector(".team-panel"),transfer=$("transfers"),fixture=$("fixtures"),league=$("leagues"),clubTable=$("clubTable"),playerStatsPanel=$("playerStats");if(view==="dashboard"){[hero,competition,stats].filter(Boolean).forEach(el=>el.classList.remove("view-hidden"))}else if(view==="squad"){content.classList.remove("view-hidden");squad.classList.remove("view-hidden");team.classList.remove("view-hidden")}else{bottom.classList.remove("view-hidden");[transfer,fixture,league,clubTable,playerStatsPanel].forEach(el=>el.classList.add("view-hidden"));if(view==="transfers")transfer.classList.remove("view-hidden");if(view==="fixtures")fixture.classList.remove("view-hidden");if(view==="leagues")league.classList.remove("view-hidden");if(view==="clubs")clubTable.classList.remove("view-hidden");if(view==="player-stats")playerStatsPanel.classList.remove("view-hidden")}window.scrollTo({top:0,behavior:"smooth"});if(view==="squad")render();if(view==="transfers")renderTransfers();if(view==="fixtures")renderFixtures();if(view==="leagues")renderBotLeague();if(view==="clubs")renderClubTable();if(view==="player-stats")renderPlayerStats()}
document.querySelectorAll("[data-view]").forEach(a=>a.addEventListener("click",e=>{e.preventDefault();activateView(a.dataset.view);history.replaceState(null,"",a.getAttribute("href"))}));document.querySelectorAll(".hero-actions a").forEach(a=>a.addEventListener("click",e=>{const v=a.getAttribute("href")==="#squad"?"squad":"fixtures";e.preventDefault();activateView(v);history.replaceState(null,"",a.getAttribute("href"))}));activateView("dashboard");
