function setHourlyBackground(){const legendPhotos=["/assets/legends/thierry-henry.jpg","/assets/legends/mohamed-salah.jpg","/assets/legends/cristiano-ronaldo.jpg"];const fallbackBackground="https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=2400&q=85";const collage="linear-gradient(90deg,rgba(5,8,21,.25),rgba(5,8,21,.05) 50%,rgba(5,8,21,.3)),"+legendPhotos.map(src=>'url("'+src+'")').join(",");document.documentElement.style.setProperty("--fx-daily-bg",collage);legendPhotos.forEach(src=>{const img=new Image();img.onerror=()=>document.documentElement.style.setProperty("--fx-daily-bg",'url("'+fallbackBackground+'")');img.src=src})}
let backgroundHour=new Date().getHours();setInterval(()=>{const nowHour=new Date().getHours();if(nowHour!==backgroundHour){backgroundHour=nowHour;setHourlyBackground()}},60000);
